// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public {
        c = new MyContract();
        vm.deal(address(c), 100 ether);
    }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount <= address(c).balance);
        address payable receiver = payable(makeAddr("receiver"));
        uint256 balanceBefore = address(c).balance;
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter < balanceBefore);
    }
}
